//! Source-neutral reporting DATA; no source/coverage/known-registry authority.
use crate::{lint::Sink,tree::SourceFile};
pub trait Reporter{fn allowed(&mut self,file:&SourceFile,line:usize,name:&str)->bool;fn allowed_here(&mut self,file:&SourceFile,line:usize,name:&str)->bool;fn site_in_msg(&mut self,rule:&str,relative:&str,line:usize,message:impl AsRef<str>);fn site_in(&mut self,rule:&str,relative:&str,line:usize);fn note(&mut self,message:impl AsRef<str>);fn sites_len(&self)->usize;fn checkpoint(&mut self)->bool{true}}
impl Reporter for Sink<'_>{fn allowed(&mut self,file:&SourceFile,line:usize,name:&str)->bool{Sink::allowed(self,file,line,name)}fn allowed_here(&mut self,file:&SourceFile,line:usize,name:&str)->bool{Sink::allowed_here(self,file,line,name)}fn site_in_msg(&mut self,rule:&str,relative:&str,line:usize,message:impl AsRef<str>){Sink::site_in_msg(self,rule,relative,line,message.as_ref())}fn site_in(&mut self,rule:&str,relative:&str,line:usize){Sink::site_in(self,rule,relative,line)}fn note(&mut self,message:impl AsRef<str>){Sink::note(self,message.as_ref())}fn sites_len(&self)->usize{self.sites.len()}}

// Checked operation-local growth for new native folds; compatibility retains original allocation behavior.
pub(crate) fn row<C:crate::key_policy_control::Control,T>(c:&mut C,v:&mut Vec<T>)->Result<(),C::Error>{if !C::CHECKED||v.len()<v.capacity(){return Ok(())}let target=v.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;crate::key_policy_control::reserve(c,||bound.checked_mul(std::mem::size_of::<T>())?.checked_add(128))?;v.try_reserve_exact(target-v.len()).map_err(|_|c.allocation_failed())?;if v.capacity()>bound{return Err(c.allocation_failed())}Ok(())}
pub(crate) fn own<C:crate::key_policy_control::Control>(c:&mut C,s:&str)->Result<String,C::Error>{crate::key_policy_control::reserve(c,||s.len().checked_mul(4)?.checked_add(128))?;let value=s.to_owned();if C::CHECKED&&value.capacity()>s.len().saturating_mul(4).saturating_add(128){return Err(c.allocation_failed())}Ok(value)}
pub(crate) fn peak<C:crate::key_policy_control::Control>(c:&mut C,held:&mut usize,bytes:impl FnOnce()->Option<usize>)->Result<(),C::Error>{if !C::CHECKED{return Ok(())}let n=bytes().ok_or_else(||c.overflow())?;if n>*held{c.reserve(n-*held)?;*held=n;}c.checkpoint()}
